// â”€â”€â”€ Config â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
function cfg() {
  let supplied = {};
  try {
    const all = globalThis.__nuvioConfig || globalThis.__pluginConfig || globalThis.__repoConfig || {};
    supplied = all[ADDON_ID] || all.current || all.tmdb || all.config || {};
  } catch (_) {}
  try {
    if (typeof userConfig !== 'undefined' && userConfig) {
      supplied = Object.assign({}, supplied, userConfig);
    }
  } catch (_) {}
  try {
    if (globalThis.__config && typeof globalThis.__config === 'object') {
      supplied = Object.assign({}, supplied, globalThis.__config);
    }
  } catch (_) {}
  // Valores booleanos / checkboxes: normalizar "true"/"false" string
  const out = Object.assign({}, DEFAULTS, supplied);
  return out;
}

function getConfig(key, def) {
  const c = cfg();
  if (c[key] != null && c[key] !== '') return c[key];
  return def != null ? def : DEFAULTS[key];
}

function apiKey() {
  const k = String(getConfig('tmdb_api_key', DEFAULTS.tmdb_api_key) || '').trim();
  return k || DEFAULTS.tmdb_api_key;
}

function lang() {
  const l = String(getConfig('tmdb_lang', 'es-MX') || 'es-MX').replace('_', '-');
  if (/^es[-_]?mx$/i.test(l)) return 'es-MX';
  if (/^es[-_]?es$/i.test(l) || /^es$/i.test(l)) return 'es-ES';
  if (/^en/i.test(l)) return 'en-US';
  return l;
}

function posterSize() {
  const q = String(getConfig('image_quality', 'w500'));
  if (['w185', 'w342', 'w500', 'w780', 'original'].includes(q)) return q;
  return 'w500';
}

function backdropSize() {
  const q = String(getConfig('backdrop_quality', 'w1280'));
  if (['w780', 'w1280', 'original'].includes(q)) return q;
  return 'w1280';
}

function region() {
  return String(getConfig('region', 'MX') || 'MX').toUpperCase();
}

function truthy(v) {
  return /^(1|true|yes|on|si|sÃ­)$/i.test(String(v == null ? '' : v).trim());
}

function includeTheater() {
  return truthy(getConfig('include_theater', 'true'));
}

function onlyDigital() {
  return truthy(getConfig('only_digital', 'true'));
}
function excludeInTheater() {
  // Preferencia general: no mostrar lo que sigue solo en cines
  if (truthy(getConfig('exclude_in_theater', 'true'))) return true;
  // Compat: only_digital / include_theater invertido
  if (truthy(getConfig('only_digital', 'true'))) return true;
  if (!truthy(getConfig('include_theater', 'false'))) return true;
  return false;
}

function digitalReleaseParams(params, isTv) {
  params = params || {};
  if (!excludeInTheater()) return params;
  const today = new Date().toISOString().slice(0, 10);
  if (isTv) {
    params['first_air_date.lte'] = today;
  } else {
    // Tipos digitales/fÃ­sicos/TV (no solo estreno en sala)
    params.with_release_type = '4|5|6';
    params['primary_release_date.lte'] = today;
  }
  return params;
}


function hideUnreleasedEps() {
  return truthy(getConfig('hide_unreleased_eps', 'true'));
}

function enabledSources() {
  const c = cfg();

  // 1) PRIORIDAD: toggles/checkboxes del usuario (source_embed69, etc.)
  //    Solo se buscan extractores en los que estÃ©n en true.
  const selected = [];
  let sawToggle = false;
  for (let i = 0; i < ALL_EXTRACTORS.length; i++) {
    const name = ALL_EXTRACTORS[i];
    const keys = ['source_' + name, 'src_' + name, 'extractor_' + name, 'server_' + name];
    let val = null;
    let found = false;
    for (let k = 0; k < keys.length; k++) {
      const key = keys[k];
      if (Object.prototype.hasOwnProperty.call(c, key) && c[key] !== undefined && c[key] !== null && c[key] !== '') {
        val = c[key];
        found = true;
        break;
      }
    }
    if (found) {
      sawToggle = true;
      if (truthy(val)) selected.push(name);
    }
  }
  if (sawToggle) {
    console.log('[streams] extractores (toggles): ' + (selected.length ? selected.join(',') : '(ninguno activo)'));
    return selected;
  }

  // 2) Override manual: enabled_sources como lista separada por comas / array
  const rawList = c.enabled_sources;
  if (rawList != null && String(rawList).trim() !== '') {
    let arr;
    if (Array.isArray(rawList)) {
      arr = rawList.map(function (s) { return String(s).trim().toLowerCase(); }).filter(Boolean);
    } else {
      arr = String(rawList)
        .split(/[,;\s]+/)
        .map(function (s) { return s.trim().toLowerCase(); })
        .filter(Boolean);
    }
    // Solo nombres conocidos
    const allowed = {};
    for (let i = 0; i < ALL_EXTRACTORS.length; i++) allowed[ALL_EXTRACTORS[i]] = true;
    arr = arr.filter(function (n) { return allowed[n]; });
    if (arr.length) {
      console.log('[streams] extractores (enabled_sources): ' + arr.join(','));
      return arr;
    }
  }

  // 3) Sin config del usuario â†’ todos (primera instalaciÃ³n)
  console.log('[streams] extractores (default todos): ' + ALL_EXTRACTORS.join(','));
  return ALL_EXTRACTORS.slice();
}

function maxConcurrent() {
  const n = parseInt(getConfig('max_concurrent_sources', '4'), 10);
  return Number.isFinite(n) && n > 0 ? Math.min(n, 10) : 4;
}

// â”€â”€â”€ HTTP / cache â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const responseCache = new Map();
const inFlight = new Map();
const MAX_CACHE = 200;

function limitMap(map, max) {
  while (map.size > max) {
    const first = map.keys().next().value;
    map.delete(first);
  }
}

async function cached(key, ttl, work) {
  const now = Date.now();
  const hit = responseCache.get(key);
  if (hit && hit.expires > now) return hit.value;
  if (hit) responseCache.delete(key);
  if (inFlight.has(key)) return inFlight.get(key);

  const task = Promise.resolve()
    .then(work)
    .then((value) => {
      if (ttl > 0) {
        responseCache.set(key, { value, expires: Date.now() + ttl });
        limitMap(responseCache, MAX_CACHE);
      }
      return value;
    })
    .finally(() => inFlight.delete(key));

  inFlight.set(key, task);
  return task;
}

async function tmdbFetch(path, params) {
  const q = Object.assign(
    { api_key: apiKey(), language: lang() },
    params || {}
  );
  const qs = Object.keys(q)
    .filter((k) => q[k] != null && q[k] !== '')
    .map((k) => encodeURIComponent(k) + '=' + encodeURIComponent(String(q[k])))
    .join('&');
  const url = TMDB + path + (path.includes('?') ? '&' : '?') + qs;
  const opts = { method: 'GET', headers: { Accept: 'application/json' } };
  if (typeof AbortSignal !== 'undefined' && typeof AbortSignal.timeout === 'function') {
    opts.signal = AbortSignal.timeout(12000);
  }
  const res = await fetch(url, opts);
  if (!res.ok) throw new Error('TMDB ' + res.status + ' ' + path);
  return res.json();
}

function posterUrl(path, size) {
  if (!path) return null;
  if (/^https?:\/\//i.test(path)) return path;
  return IMG + (size || posterSize()) + path;
}

function backdropUrl(path, size) {
  if (!path) return null;
  if (/^https?:\/\//i.test(path)) return path;
  return IMG + (size || backdropSize()) + path;
}

