async function getDiscover(opts) {
  opts = opts || {};
  const page = parseInt(opts.page || 1, 10) || 1;

  // App envÃ­a { page, type, genre, sort } segÃºn ids de getDiscoverFilters
  let type = String(opts.type || opts.kind || opts.media || 'movie').toLowerCase();
  let genre = String(opts.genre || opts.genreId || opts.with_genres || '').trim();
  let sort = String(opts.sort || opts.sort_by || opts.order || 'popularity.desc').trim();
  const filter = String(opts.filter || opts.catalog || opts.category || '').trim();

  if (filter === 'movie' || filter === 'tv') type = filter;
  if (type === 'series' || type === 'show') type = 'tv';
  if (type !== 'tv') type = 'movie';

  // GÃ©nero con prefijo m28 / t18
  if (/^m\d+$/i.test(genre)) {
    type = 'movie';
    genre = genre.slice(1);
  } else if (/^t\d+$/i.test(genre)) {
    type = 'tv';
    genre = genre.slice(1);
  } else if (genre === 'all') {
    genre = '';
  }

  // Orden genÃ©rico date/title â†’ campo TMDB
  if (sort === 'date.desc') sort = type === 'tv' ? 'first_air_date.desc' : 'primary_release_date.desc';
  if (sort === 'date.asc') sort = type === 'tv' ? 'first_air_date.asc' : 'primary_release_date.asc';
  if (sort === 'title.asc') sort = type === 'tv' ? 'name.asc' : 'original_title.asc';
  if (sort === 'title.desc') sort = type === 'tv' ? 'name.desc' : 'original_title.desc';
  if (type === 'tv') {
    sort = sort.replace('primary_release_date', 'first_air_date').replace('original_title', 'name');
  } else {
    sort = sort.replace('first_air_date', 'primary_release_date');
  }
  if (!sort) sort = 'popularity.desc';

  const path = type === 'tv' ? '/discover/tv' : '/discover/movie';
  let params = {
    page: page,
    sort_by: sort,
    include_adult: false,
    region: region(),
  };
  if (genre) params.with_genres = genre;
  params = digitalReleaseParams(params, type === 'tv');

  return cached(
    'disc:' + type + ':' + genre + ':' + sort + ':' + page + ':' + lang() + ':' + (excludeInTheater() ? '1' : '0'),
    90e3,
    async () => {
      const data = await tmdbFetch(path, params);
      const items = (data.results || []).map((r) =>
        mapTmdbItem(r, type === 'tv' ? 'tv' : 'movie')
      );
      const totalPages = data.total_pages || 1;
      return {
        items: items,
        metas: items,
        results: items,
        page: page,
        totalPages: totalPages,
        hasMore: page < totalPages,
      };
    }
  );
}


// â”€â”€â”€ Meta (logo, seasons, all episodes, IMDb) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const imdbByTmdb = new Map(); // "movie:123" | "tv:123" â†’ ttâ€¦

async function pickLogo(images) {
  const logos = (images && images.logos) || [];
  if (!logos.length) return null;
  const scored = logos
    .filter((l) => l.file_path)
    .map((l) => {
      let s = 0;
      if (l.iso_639_1 === 'es') s += 12;
      else if (l.iso_639_1 === 'en') s += 6;
      else if (!l.iso_639_1) s += 3;
      const ar = l.aspect_ratio || 0;
      if (ar >= 1.5 && ar <= 5) s += 4;
      s += Math.min(3, (l.vote_average || 0) / 3);
      return { path: l.file_path, s };
    })
    .sort((a, b) => b.s - a.s);
  return scored.length ? posterUrl(scored[0].path, 'w500') : null;
}

async function getMeta(id, options) {
  const opts =
    options && typeof options === 'object'
      ? options
      : typeof options === 'string'
        ? { type: options }
        : {};
  let { tmdbId, mediaType, isImdb } = parseContentId(id);

  if (opts.type === 'series' || opts.type === 'tv' || opts.type === 'show') {
    mediaType = 'tv';
  } else if (opts.type === 'movie') {
    mediaType = 'movie';
  }

  // IMDb â†’ TMDB
  if (isImdb || /^tt\d+/i.test(String(tmdbId))) {
    const find = await tmdbFetch('/find/' + tmdbId, {
      external_source: 'imdb_id',
    });
    const movie = (find.movie_results || [])[0];
    const tv = (find.tv_results || [])[0];
    if (movie) {
      tmdbId = String(movie.id);
      mediaType = 'movie';
    } else if (tv) {
      tmdbId = String(tv.id);
      mediaType = 'tv';
    } else {
      return { id: String(id), title: 'No encontrado', type: mediaType };
    }
  }

  return cached(
    'meta:' + mediaType + ':' + tmdbId + ':' + lang(),
    6 * 60e3,
    async () => {
      let data;
      try {
        data = await tmdbFetch('/' + mediaType + '/' + tmdbId, {
          append_to_response: 'credits,external_ids,videos,images',
          include_image_language: lang().slice(0, 2) + ',en,null',
        });
      } catch (e1) {
        const other = mediaType === 'tv' ? 'movie' : 'tv';
        data = await tmdbFetch('/' + other + '/' + tmdbId, {
          append_to_response: 'credits,external_ids,videos,images',
          include_image_language: lang().slice(0, 2) + ',en,null',
        });
        mediaType = other;
      }

      const isTv = mediaType === 'tv';
      const title = data.title || data.name || 'Sin tÃ­tulo';
      const year = String(data.release_date || data.first_air_date || '').slice(0, 4);
      const genres = (data.genres || []).map((g) => g.name);
      const imdb = (data.external_ids && data.external_ids.imdb_id) || null;
      const key = (isTv ? 'tv:' : 'movie:') + tmdbId;
      if (imdb) {
        imdbByTmdb.set(key, imdb);
        imdbByTmdb.set(String(tmdbId), imdb);
        limitMap(imdbByTmdb, 500);
      }

      const logo = await pickLogo(data.images);
      const poster = posterUrl(data.poster_path);
      const backdrop = backdropUrl(data.backdrop_path) || poster;

      const cast = ((data.credits && data.credits.cast) || [])
        .slice(0, 15)
        .map((c) => ({
          name: c.name,
          character: c.character,
          profile: posterUrl(c.profile_path, 'w185'),
        }));

      const directors = ((data.credits && data.credits.crew) || [])
        .filter((c) => c.job === 'Director' || c.job === 'Creator')
        .map((c) => c.name);

      // Temporadas + episodios
      const seasons = [];
      if (isTv && Array.isArray(data.seasons)) {
        const list = data.seasons.filter((s) => s.season_number > 0);
        // Cargar todas las temporadas (en paralelo, batches de 4)
        const batch = 4;
        for (let i = 0; i < list.length; i += batch) {
          const chunk = list.slice(i, i + batch);
          await Promise.all(
            chunk.map(async (s) => {
              try {
                const sd = await tmdbFetch(
                  '/tv/' + tmdbId + '/season/' + s.season_number
                );
                let episodes = (sd.episodes || []).map((ep) => ({
                  episode: ep.episode_number,
                  number: ep.episode_number,
                  id: 'tv:' + tmdbId,
                  contentId: 'tv:' + tmdbId,
                  title: ep.name || 'Episodio ' + ep.episode_number,
                  name: ep.name || 'Episodio ' + ep.episode_number,
                  overview: ep.overview || '',
                  description: ep.overview || '',
                  still: posterUrl(ep.still_path, 'w300'),
                  backdrop: posterUrl(ep.still_path, 'w780'),
                  runtime: ep.runtime || null,
                  airDate: ep.air_date || null,
                  rating: ep.vote_average || null,
                  season: s.season_number,
                }));

                if (hideUnreleasedEps()) {
                  const today = new Date().toISOString().slice(0, 10);
                  episodes = episodes.filter(
                    (ep) => !ep.airDate || ep.airDate <= today
                  );
                }

                seasons.push({
                  number: s.season_number,
                  season: s.season_number,
                  title: s.name || 'Temporada ' + s.season_number,
                  name: s.name || 'Temporada ' + s.season_number,
                  poster: posterUrl(s.poster_path),
                  overview: s.overview || '',
                  episodeCount: episodes.length,
                  episodes,
                });
              } catch (_) {
                seasons.push({
                  number: s.season_number,
                  season: s.season_number,
                  title: s.name || 'Temporada ' + s.season_number,
                  name: s.name || 'Temporada ' + s.season_number,
                  poster: posterUrl(s.poster_path),
                  overview: s.overview || '',
                  episodeCount: s.episode_count || 0,
                  episodes: [],
                });
              }
            })
          );
        }
        seasons.sort((a, b) => a.number - b.number);
      }

      // Intro/outro a nivel meta (pelÃ­cula) â€” el player tambiÃ©n los pide en streams
      let segments = null;
      if (imdb) {
        try {
          segments = await fetchIntroDbSegments(
            imdb,
            0,
            0,
            !isTv
          );
        } catch (_) {}
      }

      return {
        id: key,
        contentId: key,
        tmdbId: String(tmdbId),
        imdbId: imdb,
        imdb,
        title,
        name: title,
        originalTitle: data.original_title || data.original_name || title,
        poster,
        backdrop,
        background: backdrop,
        logo,
        overview: data.overview || '',
        description: data.overview || '',
        type: isTv ? 'series' : 'movie',
        media_type: isTv ? 'series' : 'movie',
        programType: isTv ? 'series' : 'movie',
        rating: data.vote_average,
        year,
        genres,
        runtime:
          data.runtime ||
          (data.episode_run_time && data.episode_run_time[0]) ||
          null,
        status: data.status,
        seasons,
        cast,
        directors,
        tagline: data.tagline || '',
        segments: segments || undefined,
        skip: segments || undefined,
        extra: { logo, imdbId: imdb },
      };
    }
  );
}

// â”€â”€â”€ IntroDB â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const introdbCache = new Map();

function rangeFromSegment(seg) {
  if (!seg || typeof seg !== 'object') return null;
  const a = Number(seg.start_sec);
  const b = Number(seg.end_sec);
  if (!Number.isFinite(a) || !Number.isFinite(b) || b <= a) return null;
  return [Math.floor(a), Math.ceil(b)];
}

async function fetchIntroDbSegments(imdbId, season, episode, isMovie) {
  const id = String(imdbId || '').trim();
  if (!/^tt\d{7,}$/i.test(id)) return null;
  const ck =
    id.toLowerCase() +
    (isMovie ? ':movie' : ':s' + Number(season || 1) + 'e' + Number(episode || 1));
  if (introdbCache.has(ck)) return introdbCache.get(ck);

  let url = INTRODB + '?imdb_id=' + encodeURIComponent(id);
  if (!isMovie) {
    url +=
      '&season=' +
      encodeURIComponent(String(Number(season || 1) || 1)) +
      '&episode=' +
      encodeURIComponent(String(Number(episode || 1) || 1));
  }
  try {
    const opts = { method: 'GET', headers: { Accept: 'application/json' } };
    if (typeof AbortSignal !== 'undefined' && typeof AbortSignal.timeout === 'function') {
      opts.signal = AbortSignal.timeout(5000);
    }
    const res = await fetch(url, opts);
    if (!res.ok) {
      introdbCache.set(ck, null);
      return null;
    }
    const json = await res.json();
    const intro = rangeFromSegment(json && json.intro);
    const outro = rangeFromSegment(json && json.outro);
    const segments = {};
    if (intro) segments.intro = intro;
    if (outro) segments.outro = outro;
    const out = segments.intro || segments.outro ? segments : null;
    introdbCache.set(ck, out);
    limitMap(introdbCache, 300);
    return out;
  } catch (_) {
    introdbCache.set(ck, null);
    return null;
  }
}

async function resolveImdbFor(tmdbId, mediaType) {
  const key = (mediaType === 'tv' ? 'tv:' : 'movie:') + tmdbId;
  if (imdbByTmdb.has(key)) return imdbByTmdb.get(key);
  if (imdbByTmdb.has(String(tmdbId))) return imdbByTmdb.get(String(tmdbId));
  try {
    const data = await tmdbFetch('/' + mediaType + '/' + tmdbId + '/external_ids');
    const imdb = data && data.imdb_id;
    if (imdb && /^tt\d+/i.test(imdb)) {
      imdbByTmdb.set(key, imdb);
      imdbByTmdb.set(String(tmdbId), imdb);
      return imdb;
    }
  } catch (_) {}
  return '';
}

// â”€â”€â”€ OpenSubtitles (Stremio v3) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const opensubsCache = new Map();

function mapSubLang(code) {
  const c = String(code || '').toLowerCase();
  if (c === 'spa' || c === 'es' || c === 'esp' || c === 'es-es' || c === 'es-mx' || c === 'spl') return 'es';
  if (c === 'eng' || c === 'en' || c === 'en-us' || c === 'en-gb') return 'en';
  if (c === 'por' || c === 'pob' || c === 'pt' || c === 'pt-br' || c === 'pb') return 'pt';
  if (c === 'fre' || c === 'fra' || c === 'fr') return 'fr';
  if (c === 'ger' || c === 'deu' || c === 'de') return 'de';
  if (c === 'ita' || c === 'it') return 'it';
  if (c === 'jpn' || c === 'ja') return 'ja';
  if (c === 'chi' || c === 'zho' || c === 'zh' || c === 'zh-cn' || c === 'zh-tw') return 'zh';
  return c || 'und';
}

function subLangPriority(langCode) {
  // Prefer Spanish (app default), then English, then others
  const l = mapSubLang(langCode);
  const appLang = (typeof lang === 'function' ? lang() : 'es-MX').toLowerCase();
  if (appLang.startsWith('es')) {
    if (l === 'es') return 0;
    if (l === 'en') return 1;
    return 2;
  }
  if (appLang.startsWith('en')) {
    if (l === 'en') return 0;
    if (l === 'es') return 1;
    return 2;
  }
  if (l === 'en') return 0;
  if (l === 'es') return 1;
  return 2;
}

/**
 * OpenSubtitles v3 (Stremio):
 *   movie:  /subtitles/movie/{imdb}.json
 *   series: /subtitles/series/{imdb}:{season}:{episode}.json
 *           /subtitles/series/{imdb}.json
 * Returns array compatible with ExternalSubtitle of the app:
 *   { lang, label, url, format }
 */
async function fetchOpenSubtitles(imdbId, mediaType, season, episode) {
  const id = String(imdbId || '').trim();
  if (!/^tt\d{7,}$/i.test(id)) return [];
  const isTv = mediaType === 'tv' || mediaType === 'series';
  const s = Number(season || 1) || 1;
  const e = Number(episode || 1) || 1;
  const ck = isTv ? id.toLowerCase() + ':s' + s + 'e' + e : id.toLowerCase() + ':movie';
  if (opensubsCache.has(ck)) return opensubsCache.get(ck) || [];

  let path;
  if (isTv) {
    path = '/series/' + id + ':' + s + ':' + e + '.json';
  } else {
    path = '/movie/' + id + '.json';
  }
  const url = OPENSUBTITLES + path;

  try {
    const opts = { method: 'GET', headers: { Accept: 'application/json' } };
    if (typeof AbortSignal !== 'undefined' && typeof AbortSignal.timeout === 'function') {
      opts.signal = AbortSignal.timeout(8000);
    }
    const res = await fetch(url, opts);
    if (!res.ok) {
      // Fallback series without episode
      if (isTv) {
        const res2 = await fetch(OPENSUBTITLES + '/series/' + id + '.json', opts).catch(function () { return null; });
        if (!res2 || !res2.ok) {
          opensubsCache.set(ck, []);
          return [];
        }
        const json2 = await res2.json();
        const list2 = normalizeOpenSubs(json2, s, e);
        opensubsCache.set(ck, list2);
        limitMap(opensubsCache, 200);
        return list2;
      }
      opensubsCache.set(ck, []);
      return [];
    }
    const json = await res.json();
    const list = normalizeOpenSubs(json, isTv ? s : 0, isTv ? e : 0);
    opensubsCache.set(ck, list);
    limitMap(opensubsCache, 200);
    return list;
  } catch (err) {
    console.log('[OpenSubs] error: ' + (err && err.message ? err.message : err));
    opensubsCache.set(ck, []);
    return [];
  }
}

function normalizeOpenSubs(json, season, episode) {
  const raw = (json && json.subtitles) || [];
  if (!Array.isArray(raw) || !raw.length) return [];

  const out = [];
  const seenUrl = new Set();

  for (let i = 0; i < raw.length; i++) {
    const s = raw[i];
    if (!s || !s.url) continue;
    // Solo subtÃ­tulos en espaÃ±ol (lang === "spa") de la API OpenSubtitles
    const rawLang = String(s.lang || s.language || '').toLowerCase();
    if (rawLang !== 'spa') continue;
    const url = String(s.url).trim();
    if (!url || seenUrl.has(url)) continue;
    // If episode filter returned extras without matching s/e, skip when we know them
    if (season > 0 && s.season != null && Number(s.season) !== Number(season)) continue;
    if (episode > 0 && s.episode != null && Number(s.episode) !== Number(episode)) continue;

    seenUrl.add(url);
    const lang = 'spa';
    const fileName = s.subtitleFileName || s.fileName || '';
    const release = s.movieReleaseName || s.releaseGroup || '';
    let label = 'SPA';
    if (fileName) {
      label = 'SPA Â· ' + String(fileName).replace(/\.srt$/i, '').slice(0, 48);
    } else if (release) {
      label = 'SPA Â· ' + String(release).slice(0, 40);
    }
    let format = 'srt';
    const lower = url.toLowerCase() + ' ' + String(fileName).toLowerCase();
    if (lower.includes('.vtt')) format = 'vtt';
    else if (lower.includes('.ass') || lower.includes('.ssa')) format = 'ass';
    else if (lower.includes('.srt')) format = 'srt';

    out.push({
      lang: lang,
      label: label,
      url: url,
      format: format,
      id: s.id != null ? String(s.id) : undefined,
      SubEncoding: s.SubEncoding || undefined,
    });
  }

  // Orden: idioma preferido â†’ resto; limitar para no saturar el menÃº del player
  out.sort(function (a, b) {
    const pa = subLangPriority(a.lang);
    const pb = subLangPriority(b.lang);
    if (pa !== pb) return pa - pb;
    return 0;
  });
  return out.slice(0, 25);
}


// â”€â”€â”€ Search â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
async function search(query) {
  if (!query || !String(query).trim()) return { items: [] };
  return cached('search:' + query + ':' + lang(), 30e3, async () => {
    const data = await tmdbFetch('/search/multi', {
      query: String(query).trim(),
      include_adult: false,
      page: 1,
    });
    const items = (data.results || [])
      .filter((r) => r.media_type === 'movie' || r.media_type === 'tv')
      .map((r) => mapTmdbItem(r, r.media_type));
    return { items, metas: items, results: items };
  });
}

// â”€â”€â”€ Extractors / Streams â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
/**
 * Extractores: se cargan desde __EXTRACTOR_SOURCES (cÃ³digo embebido) si existe,
 * o desde globalThis[name], o se dejan stubs documentados.
 * Firma: getStreams(tmdbId, mediaType, season, episode) â†’ streams[]
 *
 * Fuentes por defecto:
 *   embed69, vimeus, lamovie, elifilms, homecine,
 *   seriesmetro, cinecalidad, tioplus, verpelis
 */
const __loadedExtractors = {};

function loadExtractor(name) {
  if (__loadedExtractors[name] !== undefined) return __loadedExtractors[name];
  const n = String(name).toLowerCase();

  // 1) CÃ³digo embebido (mismo patrÃ³n que el repo de catÃ¡logos)
  try {
    const code =
      typeof __EXTRACTOR_SOURCES !== 'undefined' && __EXTRACTOR_SOURCES
        ? __EXTRACTOR_SOURCES[n]
        : null;
    if (code) {
      const module = { exports: {} };
      const exports = module.exports;
      const fn = new Function(
        'module',
        'exports',
        code + '\n;return module.exports;'
      );
      const exp = fn(module, exports);
      let getStreamsFn = null;
      if (exp && typeof exp.getStreams === 'function') getStreamsFn = exp.getStreams;
      else if (typeof module.exports.getStreams === 'function')
        getStreamsFn = module.exports.getStreams;
      else if (typeof module.exports === 'function') getStreamsFn = module.exports;
      __loadedExtractors[n] = getStreamsFn;
      return getStreamsFn;
    }
  } catch (e) {
    console.log('[extractor] load error ' + n + ': ' + (e && e.message));
  }

  // 2) globalThis registrado
  try {
    const g = globalThis['extractor_' + n] || globalThis[n];
    if (g && typeof g.getStreams === 'function') {
      __loadedExtractors[n] = g.getStreams.bind(g);
      return __loadedExtractors[n];
    }
    if (typeof g === 'function') {
      __loadedExtractors[n] = g;
      return g;
    }
  } catch (_) {}

  __loadedExtractors[n] = null;
  return null;
}

function normalizeStream(s, sourceName) {
  if (!s) return null;
  const url = String(s.url || s.file || s.src || s.link || s.stream || '').trim();
  if (!url || url.indexOf('http') !== 0) return null;
  const lower = url.toLowerCase();
  return {
    name: s.name || sourceName,
    title: s.title || s.name || sourceName,
    url,
    quality: s.quality || s.q || 'HD',
    language: s.language || s.lang || s.Audio || 'Latino',
    server: s.server || s.serverLabel || sourceName,
    headers: s.headers || null,
    isHls: /\.m3u8|hls|manifest/i.test(lower),
    isMp4: /\.mp4/i.test(lower),
    source: sourceName,
    provider: sourceName,
    // Passthrough segmentos si el extractor los trae
    segments: s.segments || s.skip || null,
    subtitles: s.subtitles || s.subs || null,
  };
}

async function getStreams(id, type, season, episode) {
  let { tmdbId, mediaType } = parseContentId(id);

  if (id && typeof id === 'object') {
    tmdbId = String(id.tmdbId || id.id || tmdbId).replace(/^(movie|tv|series)[:/]/i, '');
    mediaType =
      id.type === 'tv' || id.type === 'series'
        ? 'tv'
        : id.type === 'movie'
          ? 'movie'
          : mediaType;
    season = id.season != null ? id.season : season;
    episode = id.episode != null ? id.episode : episode;
  }

  if (type === 'series' || type === 'tv' || type === 'show') mediaType = 'tv';
  else if (type === 'movie') mediaType = 'movie';

  if (/^tt\d+/i.test(String(tmdbId))) {
    try {
      const find = await tmdbFetch('/find/' + tmdbId, { external_source: 'imdb_id' });
      const movie = (find.movie_results || [])[0];
      const tv = (find.tv_results || [])[0];
      if (movie) {
        tmdbId = String(movie.id);
        mediaType = 'movie';
      } else if (tv) {
        tmdbId = String(tv.id);
        mediaType = 'tv';
      }
    } catch (_) {}
  }

  tmdbId = String(tmdbId).replace(/^(movie|tv|series)[:/]/i, '');

  // IMDb + IntroDB + OpenSubtitles (player: segmentos + subtÃ­tulos externos)
  let streamSegments = null;
  let streamSubtitles = [];
  try {
    const imdb = await resolveImdbFor(tmdbId, mediaType);
    if (imdb) {
      const isTv = mediaType === 'tv' || mediaType === 'series';
      const [segs, subs] = await Promise.all([
        isTv
          ? fetchIntroDbSegments(imdb, season || 1, episode || 1, false)
          : fetchIntroDbSegments(imdb, 0, 0, true),
        fetchOpenSubtitles(imdb, mediaType, season || 1, episode || 1),
      ]);
      streamSegments = segs;
      streamSubtitles = Array.isArray(subs) ? subs : [];
    }
  } catch (_) {}

  // SOLO extractores que el usuario activÃ³ en config (toggles)
  const names = enabledSources().filter(function (n) {
    return ALL_EXTRACTORS.indexOf(String(n).toLowerCase()) !== -1;
  });
  if (!names.length) {
    console.warn('[getStreams] ningÃºn extractor activo en config â€” no se buscarÃ¡n servidores');
    return [];
  }
  console.log('[getStreams] buscando SOLO en: ' + names.join(', '));
  const limit = maxConcurrent();
  const allStreams = [];
  const seen = {};
  const queue = names.slice();

  async function worker() {
    while (queue.length) {
      const name = queue.shift();
      try {
        const fn = loadExtractor(name);
        if (!fn) {
          console.log('[getStreams] extractor no cargado: ' + name);
          continue;
        }
        const raw = await Promise.race([
          Promise.resolve(
            fn.call(null, String(tmdbId), mediaType, season || null, episode || null)
          ),
          new Promise((_, rej) =>
            setTimeout(() => rej(new Error('timeout')), 22000)
          ),
        ]);
        const list = Array.isArray(raw) ? raw : (raw && raw.streams) || [];
        for (let i = 0; i < list.length; i++) {
          const ns = normalizeStream(list[i], name);
          if (!ns) continue;
          const key = ns.url.split('?')[0];
          if (seen[key]) continue;
          seen[key] = true;
          if (streamSegments && !ns.segments) {
            ns.segments = streamSegments;
            ns.skip = streamSegments;
            ns.markers = streamSegments;
          }
          // SubtÃ­tulos OpenSubtitles (si el extractor no trajo los suyos)
          if (streamSubtitles && streamSubtitles.length) {
            if (!ns.subtitles || !ns.subtitles.length) {
              ns.subtitles = streamSubtitles;
              ns.subs = streamSubtitles;
            } else {
              // Combinar sin duplicar URL
              const have = new Set(
                (ns.subtitles || []).map(function (x) { return String(x && x.url || ''); })
              );
              for (let si = 0; si < streamSubtitles.length; si++) {
                const su = streamSubtitles[si];
                if (su && su.url && !have.has(su.url)) {
                  ns.subtitles.push(su);
                  have.add(su.url);
                }
              }
              ns.subs = ns.subtitles;
            }
          }
          allStreams.push(ns);
        }
      } catch (e) {
        console.log(
          '[getStreams] ' + name + ' error: ' + (e && e.message ? e.message : e)
        );
      }
    }
  }

  const workers = [];
  for (let w = 0; w < Math.min(limit, names.length); w++) workers.push(worker());
  await Promise.all(workers);

  allStreams.sort((a, b) => {
    if (a.isHls && !b.isHls) return -1;
    if (!a.isHls && b.isHls) return 1;
    return 0;
  });

  // Si no hubo extractores, devolver placeholder con segmentos para depurar player
  if (!allStreams.length && (streamSegments || (streamSubtitles && streamSubtitles.length))) {
    return [
      {
        name: 'IntroDB / Subs only',
        title: 'Sin servidores â€” segmentos/subtÃ­tulos disponibles',
        url: 'https://example.invalid/no-stream',
        quality: 'N/A',
        language: 'â€”',
        segments: streamSegments || undefined,
        skip: streamSegments || undefined,
        markers: streamSegments || undefined,
        subtitles: streamSubtitles && streamSubtitles.length ? streamSubtitles : undefined,
        subs: streamSubtitles && streamSubtitles.length ? streamSubtitles : undefined,
      },
    ];
  }

  return allStreams;
}

// â”€â”€â”€ Config schema (para la UI de la app) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
